from pathlib import Path
import base64, json
R = Path(__file__).resolve().parents[2]
O = R / 'renders/secretgarden_reseau_v1'
m = json.loads((O / 'manifest.json').read_text())


def uri(p):
    return 'data:image/png;base64,' + base64.b64encode(p.read_bytes()).decode()


data = {}
for e in m['rooms']:
    d = O / e['id']
    data[e['id']] = {**e,
                     'images': {n: uri(d / (n + '.png')) for n in e['layers']},
                     'flowers': [uri(d / 'fleurs' / f'06_fleurs_f{i}.png') for i in range(4)],
                     'schema': uri(d / 'schema.png')}
h = '''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jardin secret · réseau connectable V2</title><style>*{box-sizing:border-box}body{margin:0;background:#1d3320;color:#eef4da;font:16px system-ui}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#cfdcc0;line-height:1.6}.tag{font-size:12px;letter-spacing:2px;color:#b8d489}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:12px;border:1px solid #6f9151;border-radius:6px;background:#33482a;color:#f4f9e8}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}canvas{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#101a10}aside{background:#24351f;padding:18px;border-radius:8px}label{display:block;margin:12px 0;font-size:14px}a{color:#d7e8b8}small{color:#b3c49b}footer{border-top:1px solid #435c36}.anim{display:flex;gap:8px;align-items:center;margin:12px 0;font-size:14px}.anim button{padding:8px 12px}@media(max-width:780px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">JARDIN SECRET / RÉSEAU STYLE LEDIAN / V3</div><h1>Sept pièces connectables · 19 accès</h1><p>Couloirs, jonction en T, salles et carrefours générés d’après secretgarden.png. Chaque zone se règle couche par couche : sol, chemin, arbres, buissons, rochers, fleurs animées, bordure jungle, raccords. Fleurs : 4 phases à 200ms comme Sky Peak.</p></header><main><div class="toolbar"><select id="room"></select><button id="plan">Voir schéma des accès</button><button id="reference">Voir référence native</button><button id="export">Exporter PNG affiché</button></div><div class="layout"><section><canvas id="view" width="512" height="512"></canvas><div class="anim"><button id="play">⏸ Pause fleurs</button><button id="step">⏭ Phase suivante</button><span id="phase">phase 0/4 · 200ms</span></div><p id="status"></p></section><aside><b>Calques alignés · 512 × 512</b><div id="layers"></div><small>Bordure jungle et raccords indépendants. Végétation et rochers : partitions visibles du rendu, pas des volumes reconstruits derrière les autres calques. La bande commune garantit le sol au passage, pas l’emboîtement de toute la silhouette végétale.</small></aside></div></main><footer><p>Source : secretgarden.png (commit utilisateur). Architectures générées guidées, pas des cartes natives originales. Le patch des raccords provient directement des pixels sources. Animation des fleurs créée pour ce lot (cadence Sky Peak), pas un cycle officiel récupéré.</p><small>19 ports de 64px : bande de 24px opaque vérifiée, fenêtres dégagées dans la bordure jungle. Ni collisions, ni transitions PMDO, ni test de navigation.</small></footer><script>const DATA=__DATA__,REF=__REF__,FLOWER='06_fleurs',c=document.getElementById('view'),ctx=c.getContext('2d'),select=document.getElementById('room');let entry,images={},flowers=[],visible={},schema=false,reference=false,playing=true,fi=0,last=0;function image(src){let im=new Image();im.src=src;return im}const ref=image(REF);function download(src,name){let a=document.createElement('a');a.href=src;a.download=name;a.click()}for(const [id,e]of Object.entries(DATA)){let o=document.createElement('option');o.value=id;o.textContent=e.title;select.append(o)}select.value='salle_carrefour';function setup(){entry=DATA[select.value];images={};flowers=entry.flowers.map(image);visible={};fi=0;const root=document.getElementById('layers');root.innerHTML='';for(const n of entry.layers){if(n===FLOWER)continue;images[n]=image(entry.images[n]);visible[n]=true;const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>visible[n]=ch.checked;a.href=entry.images[n];a.download=entry.id+'_'+n+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(n.replace(/^\\d+_/,'').replaceAll('_',' ')),a);root.append(l)}images[FLOWER]=image(entry.images[FLOWER]);visible[FLOWER]=true;const l=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=true;ch.onchange=()=>visible[FLOWER]=ch.checked;l.append(ch,document.createTextNode('fleurs animées (4 phases)'));const fl=root.children;root.insertBefore(l,fl[Math.min(8,fl.length)]);images.schema=image(entry.schema);document.getElementById('status').textContent=entry.title+' · Accès : '+entry.ports.map(p=>p.direction).join(' / ')+' · largeur de raccord 64px'}select.onchange=setup;document.getElementById('plan').onclick=e=>{schema=!schema;reference=false;e.target.textContent=schema?'Voir rendu':'Voir schéma des accès'};document.getElementById('reference').onclick=e=>{reference=!reference;e.target.textContent=reference?'Revenir à la variante':'Voir référence native'};document.getElementById('export').onclick=()=>download(c.toDataURL(),reference?'secretgarden_reference.png':entry.id+(schema?'_schema':'_f'+fi)+'.png');document.getElementById('play').onclick=e=>{playing=!playing;e.target.textContent=playing?'⏸ Pause fleurs':'▶ Animer fleurs'};document.getElementById('step').onclick=()=>{playing=false;document.getElementById('play').textContent='▶ Animer fleurs';fi=(fi+1)%4};function draw(im){if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}function render(t){if(playing&&t-last>200){last=t;fi=(fi+1)%4;document.getElementById('phase').textContent='phase '+fi+'/4 · 200ms'}const w=reference?408:512,h=reference?408:512;if(c.width!==w||c.height!==h){c.width=w;c.height=h}ctx.clearRect(0,0,c.width,c.height);if(reference)draw(ref);else if(schema)draw(images.schema);else{for(const n of entry.layers){if(n===FLOWER)continue;if(visible[n])draw(images[n])}if(visible[FLOWER]){const f=flowers[fi];if(f.complete&&f.naturalWidth)draw(f);else draw(images[FLOWER])}}requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R / 'apercu_jardin_secret_reseau_v1.html').write_text(
    h.replace('__DATA__', json.dumps(data)).replace('__REF__', json.dumps(uri(R / 'secretgarden.png'))),
    encoding='utf8')
print('gallery v2 written')
